{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, a para-substituted benzamide with a basic aminoethyl side chain closely analogous to the query, has an absolute oral bioavailability of 75% in normal volunteers compared with intravenous dosing, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Trazodone, which contains a chlorophenyl and a morpholine-containing moiety, showed an absolute oral bioavailability of 65% in fed volunteers, providing direct fed-state evidence that this chemotype is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Isoniazid, a small polar amide-like drug, showed 78% oral bioavailability in fed patients, supporting high oral bioavailability for small amide-containing molecules under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Molsidomine, which contains a morpholine ring, had an absolute oral bioavailability of 44 ± 15% in healthy volunteers, still well above the 20% threshold despite measurable first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transferability analogues with direct absolute oral bioavailability measurements, especially the closely related procainamide (75-86%) and fed-state trazodone (65%), consistently show F well above 20%. The favorable physicochemical prior and absence of contradictory evidence reinforce the high prediction.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "Fed-state data are derived from analogues rather than the query itself.",
    "Potential first-pass metabolism of the secondary amide or morpholine ring is not directly quantified for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

